"""Replicate WW36 John Snow story map with parameter-controlled spatial layers."""
from pathlib import Path
from cwtwb import TWBEditor
HERE=Path(__file__).resolve().parent; OUT=HERE/'outputs'; HYPER=HERE/'inputs'/'Deaths by Building.hyper'; DASH='2026_09_09_WW36_John_Snow_Cholera_Map'
def build(output_path:Path)->Path:
 e=TWBEditor(''); e.set_hyper_connection(str(HYPER)); e.add_parameter('pScroll','integer','1',domain_type='list',allowed_values=['1','2','3','4'],allowed_aliases={'1':'Homes and Buildings','2':'Deaths','3':'Sewerage vents','4':'Pumps'},alias='Story step')
 for name,formula in [('Building Location','IIF([pScroll]=1,MAKEPOINT([Latitude],[Longitude]),NULL)'),('Building Location (Deaths)','IIF([pScroll]=2,MAKEPOINT([Latitude],[Longitude]),NULL)'),('Sewer Location','IIF([pScroll]=3,MAKEPOINT([Latitude],[Longitude]),NULL)'),('Pump Location','IIF([pScroll]=4,MAKEPOINT([Latitude],[Longitude]),NULL)'),('Is Broad Street Pump','FALSE'),('Step 1','[pScroll]=1'),('Step 2','[pScroll]=2'),('Step 3','[pScroll]=3'),('Step 4','[pScroll]=4')]:
  dt='spatial' if 'Location' in name else ('boolean'); e.add_calculated_field(name,formula,datatype=dt,role='measure' if dt=='spatial' else 'dimension',field_type='nominal',validate_formula=False)
 e.add_worksheet('Map'); e.configure_chart('Map',mark_type='Map',geographic_field='Building Location',map_layers=[{'geometry':'Building Location','mark_type':'Circle','detail':'ID','color':'Step 1','size':'MIN(1)','tooltip':['ID','deaths','Latitude','Longitude']},{'geometry':'Building Location (Deaths)','mark_type':'Circle','detail':'ID','color':'deaths','size':'deaths','tooltip':['ID','deaths']},{'geometry':'Sewer Location','mark_type':'Circle','detail':'ID','color':'Step 3','size':'MIN(1)','tooltip':['ID']},{'geometry':'Pump Location','mark_type':'Shape','detail':'ID','color':'Step 4','size':'MIN(1)','tooltip':['ID']}])
 e.configure_worksheet_style('Map',background_color='#f5f5f5',hide_gridlines=True,hide_zeroline=True,hide_borders=True,hide_table_dividers=True,map_style={'map_style':'light','washout':0})
 layout={'type':'container','direction':'floating','style':{'background-color':'#f5f5f5'},'children':[{'type':'text','text':'#WOW2026 Week 36 | Let\'s tell a story with map layers','font_size':'18','absolute':{'x':1000,'y':1000,'w':98000,'h':7000}},{'type':'worksheet','name':'Map','show_title':False,'fit':'entire','absolute':{'x':1000,'y':10000,'w':98000,'h':70000}},{'type':'paramctrl','param':'pScroll','absolute':{'x':1000,'y':82000,'w':40000,'h':7000}},{'type':'text','text':'Choose Homes and Buildings, Deaths, Sewerage vents, or Pumps. The layer visibility is controlled by pScroll.','font_size':'11','absolute':{'x':42000,'y':82000,'w':56000,'h':7000}}]}
 e.add_dashboard(DASH,width=1366,height=768,layout=layout,worksheet_names=['Map']); OUT.mkdir(exist_ok=True); e.save(output_path,validate=False); return output_path
if __name__=='__main__': print(build(OUT/'replicated-workbook.twbx'))
